int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char *adj = (char *)calloc((size_t)N * N, sizeof(char));
    if (!adj) return 0;

    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        --a; --b;
        adj[(size_t)a * N + b] = 1;
        adj[(size_t)b * N + a] = 1;
    }

    /* Build complement graph and check bipartite.
       If original graph can be partitioned into two cliques,
       then complement graph must be bipartite. */
    int *color = (int *)malloc(sizeof(int) * N);
    int *queue = (int *)malloc(sizeof(int) * N);
    int *compA = (int *)malloc(sizeof(int) * N);
    int *compB = (int *)malloc(sizeof(int) * N);
    if (!color || !queue || !compA || !compB) return 0;

    for (int i = 0; i < N; i++) color[i] = -1;

    int comps = 0;
    for (int s = 0; s < N; s++) {
        if (color[s] != -1) continue;

        int head = 0, tail = 0;
        queue[tail++] = s;
        color[s] = 0;
        int cnt0 = 1, cnt1 = 0;

        while (head < tail) {
            int v = queue[head++];
            for (int u = 0; u < N; u++) {
                if (u == v) continue;
                if (adj[(size_t)v * N + u]) continue; /* edge in original => no edge in complement */

                if (color[u] == -1) {
                    color[u] = color[v] ^ 1;
                    if (color[u] == 0) cnt0++;
                    else cnt1++;
                    queue[tail++] = u;
                } else if (color[u] == color[v]) {
                    printf("-1\n");
                    free(adj); free(color); free(queue); free(compA); free(compB);
                    return 0;
                }
            }
        }

        compA[comps] = cnt0;
        compB[comps] = cnt1;
        comps++;
    }

    /* DP over possible sizes of one clique */
    char *dp = (char *)calloc(N + 1, sizeof(char));
    char *ndp = (char *)calloc(N + 1, sizeof(char));
    if (!dp || !ndp) return 0;

    dp[0] = 1;
    for (int i = 0; i < comps; i++) {
        memset(ndp, 0, N + 1);
        for (int s = 0; s <= N; s++) {
            if (!dp[s]) continue;
            if (s + compA[i] <= N) ndp[s + compA[i]] = 1;
            if (s + compB[i] <= N) ndp[s + compB[i]] = 1;
        }
        char *tmp = dp; dp = ndp; ndp = tmp;
    }

    ll ans = -1;
    for (int k = 0; k <= N; k++) {
        if (!dp[k]) continue;
        ll x = k;
        ll y = N - k;
        ll roads_inside = x * (x - 1) / 2 + y * (y - 1) / 2;
        if (ans == -1 || roads_inside < ans) ans = roads_inside;
    }

    printf("%lld\n", ans);

    free(adj);
    free(color);
    free(queue);
    free(compA);
    free(compB);
    free(dp);
    free(ndp);
    return 0;
}

