        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
        adj[a][b] = adj[b][a] = true;
    }

    // Build complement graph and check bipartiteness.
    // If complement graph is not bipartite, impossible.
    vector<int> color(N, -1);
    vector<pair<int,int>> comps; // sizes of the two color classes in each component

    for (int s = 0; s < N; ++s) {
        if (color[s] != -1) continue;

        queue<int> q;
        q.push(s);
        color[s] = 0;
        int cnt[2] = {1, 0};

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (int u = 0; u < N; ++u) {
                if (u == v) continue;
                if (adj[v][u]) continue; // not an edge in complement

                if (color[u] == -1) {
                    color[u] = color[v] ^ 1;
                    cnt[color[u]]++;
                    q.push(u);
                } else if (color[u] == color[v]) {
                    cout << -1 << '\n';
                    return 0;
                }
            }
        }
        comps.push_back({cnt[0], cnt[1]});
    }

    // DP: possible sizes of one group
    vector<bool> dp(N + 1, false), ndp(N + 1, false);
    dp[0] = true;

    for (auto [a, b] : comps) {
        fill(ndp.begin(), ndp.end(), false);
        for (int i = 0; i <= N; ++i) {
            if (!dp[i]) continue;
            if (i + a <= N) ndp[i + a] = true;
            if (i + b <= N) ndp[i + b] = true;
        }
        dp.swap(ndp);
    }

    long long ans = (1LL << 60);
    for (int s = 0; s <= N; ++s) {
        if (!dp[s]) continue;
        long long t = N - s;
        long long roads_inside = 1LL * s * (s - 1) / 2 + 1LL * t * (t - 1) / 2;
        ans = min(ans, roads_inside);
    }

    // Since both groups must be cliques, every pair inside a group must have a road.
    // The minimum number of roads with both endpoints in the same state equals
    // the number of pairs inside the two groups.
    cout << ans << '\n';
    return 0;
}

