public class Main {
    static List<Integer>[] graph, compGraph;
    static int[] color;
    static boolean[] visited;
    static List<Integer> component;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        graph = new ArrayList[N];
        for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();
        boolean[][] adj = new boolean[N][N];
        for (int i = 0; i < M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            graph[a].add(b);
            graph[b].add(a);
            adj[a][b] = adj[b][a] = true;
        }

        visited = new boolean[N];
        int totalInternal = 0;

        for (int i = 0; i < N; i++) {
            if (!visited[i]) {
                component = new ArrayList<>();
                dfs(i);

                int n = component.size();
                // Build complement graph within component
                Map<Integer, Integer> idx = new HashMap<>();
                for (int j = 0; j < n; j++) idx.put(component.get(j), j);
                compGraph = new ArrayList[n];
                for (int j = 0; j < n; j++) compGraph[j] = new ArrayList<>();

                for (int u : component) {
                    for (int v : component) {
                        if (u != v && !adj[u][v]) {
                            int ui = idx.get(u);
                            int vi = idx.get(v);
                            compGraph[ui].add(vi);
                        }
                    }
                }

                // Bipartite check on complement
                color = new int[n];
                Arrays.fill(color, -1);
                boolean bipartite = true;
                List<List<Integer>> parts = new ArrayList<>();
                for (int j = 0; j < n; j++) {
                    if (color[j] == -1) {
                        List<Integer> part = new ArrayList<>();
                        if (!bipartiteCheck(j, part)) {
                            bipartite = false;
                            break;
                        }
                        parts.add(part);
                    }
                }

                if (!bipartite) {
                    System.out.println(-1);
                    return;
                }

                // For each bipartite part, we have two color groups; we can flip them independently
                // We want to minimize internal edges = sum over both sides of (size*(size-1)/2)
                // Total edges inside component = n*(n-1)/2
                // Internal edges = edges inside each clique = sum sizeC2
                // We can choose assignment for each bipartite component
                // Use DP: possible sums of sizes of one side
                int total = 0;
                boolean[] possible = new boolean[n + 1];
                possible[0] = true;
                for (List<Integer> part : parts) {
                    int sz1 = 0, sz2 = 0;
                    for (int v : part) {
                        if (color[v] == 0) sz1++;
                        else sz2++;
                    }
                    boolean[] next = new boolean[n + 1];
                    for (int s = 0; s <= n; s++) {
                        if (possible[s]) {
                            next[s + sz1] = true;
                            next[s + sz2] = true;
                        }
                    }
                    possible = next;
                }

                long minInternal = Long.MAX_VALUE;
                for (int s = 0; s <= n; s++) {
                    if (possible[s]) {
                        long internal = (long)s * (s - 1) / 2 + (long)(n - s) * (n - s - 1) / 2;
                        minInternal = Math.min(minInternal, internal);
                    }
                }
                totalInternal += minInternal;
            }
        }

        System.out.println(totalInternal);
    }

    static void dfs(int u) {
        visited[u] = true;
        component.add(u);
        for (int v : graph[u]) {
            if (!visited[v]) dfs(v);
        }
    }

    static boolean bipartiteCheck(int start, List<Integer> part) {
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        color[start] = 0;
        part.add(start);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : compGraph[u]) {
                if (color[v] == -1) {
                    color[v] = 1 - color[u];
                    part.add(v);
                    q.add(v);
                } else if (color[v] == color[u]) {
                    return false;
                }
            }
        }
        return true;
    }
}

