public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        boolean[][] g = new boolean[N][N];
        int[] deg = new int[N];

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            if (!g[a][b]) {
                g[a][b] = g[b][a] = true;
                deg[a]++;
                deg[b]++;
            }
        }

        // Cities in the same state must form a clique.
        // Therefore, in the complement graph, each state must be an independent set,
        // so the complement graph must be bipartite.
        List<Integer>[] comp = new ArrayList[N];
        for (int i = 0; i < N; i++) comp[i] = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (!g[i][j]) {
                    comp[i].add(j);
                    comp[j].add(i);
                }
            }
        }

        int[] color = new int[N];
        Arrays.fill(color, -1);

        List<int[]> components = new ArrayList<>();
        ArrayDeque<Integer> q = new ArrayDeque<>();

        for (int s = 0; s < N; s++) {
            if (color[s] != -1) continue;
            color[s] = 0;
            q.add(s);
            int cnt0 = 1, cnt1 = 0;

            while (!q.isEmpty()) {
                int v = q.poll();
                for (int to : comp[v]) {
                    if (color[to] == -1) {
                        color[to] = color[v] ^ 1;
                        if (color[to] == 0) cnt0++;
                        else cnt1++;
                        q.add(to);
                    } else if (color[to] == color[v]) {
                        System.out.println(-1);
                        return;
                    }
                }
            }
            components.add(new int[]{cnt0, cnt1});
        }

        // DP over possible sizes of one state.
        boolean[] dp = new boolean[N + 1];
        dp[0] = true;

        for (int[] c : components) {
            boolean[] ndp = new boolean[N + 1];
            int a = c[0], b = c[1];
            for (int i = 0; i <= N; i++) {
                if (!dp[i]) continue;
                if (i + a <= N) ndp[i + a] = true;
                if (i + b <= N) ndp[i + b] = true;
            }
            dp = ndp;
        }

        long ans = Long.MAX_VALUE;
        for (int s = 0; s <= N; s++) {
            if (!dp[s]) continue;
            long t = N - s;
            long edgesInside = (long) s * (s - 1) / 2 + t * (t - 1) / 2;
            ans = Math.min(ans, edgesInside);
        }

        System.out.println(ans);
    }
